/*
  Twinkle Twinkle Little Star
  Passive buzzer melody player
  Board: Arduino Uno
*/

// --- Pin setup ---
const int BUZZER_PIN = 8;   // passive buzzer signal pin

// Note frequencies in Hz
#define NOTE_C4 262
#define NOTE_D4 294
#define NOTE_E4 330
#define NOTE_F4 349
#define NOTE_G4 392
#define NOTE_A4 440

// The melody, one frequency per note
int melody[] = {
  NOTE_C4, NOTE_C4, NOTE_G4, NOTE_G4, NOTE_A4, NOTE_A4, NOTE_G4,
  NOTE_F4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_D4, NOTE_D4, NOTE_C4
};

// Note lengths: 4 = quarter note, 2 = half note
int noteDurations[] = {
  4, 4, 4, 4, 4, 4, 2,
  4, 4, 4, 4, 4, 4, 2
};

const int noteCount = sizeof(melody) / sizeof(melody[0]);

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Buzzer melody demo ready");
}

void loop() {
  for (int i = 0; i < noteCount; i++) {
    // A whole note is 1000 ms, so a quarter note is 1000 / 4
    int noteLength = 1000 / noteDurations[i];

    tone(BUZZER_PIN, melody[i], noteLength);

    // Leave a small gap so two identical notes can be told apart
    int pause = noteLength * 1.30;
    delay(pause);

    noTone(BUZZER_PIN);
  }

  // Wait two seconds before playing the song again
  delay(2000);
}

