/*
  Push button siren alarm
  Sweeps the buzzer up and down while the button is held
  Board: Arduino Uno
*/

// --- Pin setup ---
const int BUZZER_PIN = 9;   // passive buzzer
const int BUTTON_PIN = 2;   // push button to GND (uses internal pull-up)
const int LED_PIN = 13;     // on board LED shows the alarm is active

// --- Siren settings ---
const int MIN_FREQ = 400;   // lowest tone in Hz
const int MAX_FREQ = 1200;  // highest tone in Hz
const int FREQ_STEP = 10;   // how fast the tone slides

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  Serial.begin(9600);
  Serial.println("Hold the button to sound the alarm");
}

void loop() {
  // With INPUT_PULLUP the pin reads LOW when the button is pressed
  if (digitalRead(BUTTON_PIN) == LOW) {
    digitalWrite(LED_PIN, HIGH);
    playSiren();
  } else {
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
  }
}

// One full up and down sweep of the siren
void playSiren() {
  for (int freq = MIN_FREQ; freq <= MAX_FREQ; freq += FREQ_STEP) {
    tone(BUZZER_PIN, freq);
    delay(5);
  }

  for (int freq = MAX_FREQ; freq >= MIN_FREQ; freq -= FREQ_STEP) {
    tone(BUZZER_PIN, freq);
    delay(5);
  }
}

