  Beep pattern generator
  Three short beeps followed by one long beep, on demand
  Board: Arduino Nano
*/

// --- Pin setup ---
const int BUZZER_PIN = 6;    // active or passive buzzer
const int BUTTON_PIN = 4;    // trigger button to GND
const int LED_PIN = 12;      // blinks together with the buzzer

// --- Beep timing (milliseconds) ---
const int SHORT_BEEP = 120;
const int LONG_BEEP = 600;
const int GAP = 150;

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  Serial.begin(9600);
  Serial.println("Press the button for the beep pattern");
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    Serial.println("Playing pattern");

    // Three short beeps
    for (int i = 0; i < 3; i++) {
      beep(SHORT_BEEP);
      delay(GAP);
    }

    // One long beep at the end
    beep(LONG_BEEP);

    // Simple way to avoid repeating while the button is still held
    delay(500);
  }
}

// Sound the buzzer and blink the LED for the given number of milliseconds
void beep(int duration) {
  digitalWrite(LED_PIN, HIGH);
  tone(BUZZER_PIN, 1000);
  delay(duration);
  noTone(BUZZER_PIN);
  digitalWrite(LED_PIN, LOW);
}

