/*
  Buzzer on ESP32 using the LEDC hardware PWM
  The ESP32 core does not have the classic tone() function,
  so we drive the buzzer with a PWM channel instead.
  Board: ESP32 Dev Module
*/

// --- Pin and PWM setup ---
const int BUZZER_PIN = 25;      // buzzer signal pin
const int PWM_CHANNEL = 0;      // LEDC channel 0
const int PWM_RESOLUTION = 8;   // 8 bit duty cycle (0 - 255)
const int BASE_FREQ = 2000;     // starting frequency in Hz

// Simple scale to play at startup
int scale[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int scaleLength = sizeof(scale) / sizeof(scale[0]);

void setup() {
  Serial.begin(115200);

  // Attach the buzzer pin to the PWM channel
  ledcSetup(PWM_CHANNEL, BASE_FREQ, PWM_RESOLUTION);
  ledcAttachPin(BUZZER_PIN, PWM_CHANNEL);

  Serial.println("ESP32 buzzer ready");
}

void loop() {
  // Play the scale going up
  for (int i = 0; i < scaleLength; i++) {
    Serial.print("Note: ");
    Serial.println(scale[i]);
    playTone(scale[i], 250);
    delay(50);
  }

  delay(1000);
}

// Play one tone for the given number of milliseconds
void playTone(int frequency, int duration) {
  ledcWriteTone(PWM_CHANNEL, frequency);
  ledcWrite(PWM_CHANNEL, 128);   // 50 percent duty cycle
  delay(duration);
  ledcWriteTone(PWM_CHANNEL, 0); // silence
}

