/*
  HC-SR04 ultrasonic distance meter
  Prints the measured distance to the Serial Monitor
  Board: Arduino Uno
*/

// --- Pin setup ---
const int TRIG_PIN = 9;   // trigger pin of the HC-SR04
const int ECHO_PIN = 10;  // echo pin of the HC-SR04

// Variables used for the measurement
long duration;
float distanceCm;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  Serial.begin(9600);
  Serial.println("HC-SR04 distance test");
}

void loop() {
  // Make sure the trigger pin starts LOW
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  // Send a 10 microsecond pulse to start a measurement
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // Measure how long the echo pin stays HIGH
  duration = pulseIn(ECHO_PIN, HIGH);

  // Sound travels about 0.034 cm per microsecond,
  // and the pulse goes out and comes back, so divide by 2
  distanceCm = duration * 0.034 / 2;

  Serial.print("Distance: ");
  Serial.print(distanceCm);
  Serial.println(" cm");

  delay(500);
}

