const int TRIG_PIN = 6;
const int ECHO_PIN = 7;

// --- Indicator pins ---
const int GREEN_LED = 2;
const int YELLOW_LED = 3;
const int RED_LED = 4;
const int BUZZER_PIN = 5;

// --- Distance thresholds in centimetres ---
const int NEAR_LIMIT = 10;
const int MID_LIMIT = 25;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  Serial.begin(9600);
  Serial.println("Obstacle warning system started");
}

void loop() {
  float distance = readDistanceCm();

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // Turn everything off first, then switch on what we need
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(RED_LED, LOW);
  noTone(BUZZER_PIN);

  if (distance < NEAR_LIMIT) {
    // Too close, warn loudly
    digitalWrite(RED_LED, HIGH);
    tone(BUZZER_PIN, 1500);
  } else if (distance < MID_LIMIT) {
    // Getting close
    digitalWrite(YELLOW_LED, HIGH);
  } else {
    // Plenty of room
    digitalWrite(GREEN_LED, HIGH);
  }

  delay(200);
}

// Take one reading and return the distance in centimetres
float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH);
  float distance = duration * 0.034 / 2;
  return distance;
}

