/*
  Car parking sensor
  The closer the wall gets, the faster the buzzer beeps
  Board: Arduino Nano
*/

// --- Pin setup ---
const int TRIG_PIN = 3;
const int ECHO_PIN = 2;
const int BUZZER_PIN = 8;

// --- Distance range we care about (cm) ---
const int MIN_DISTANCE = 5;    // anything closer is treated as 5 cm
const int MAX_DISTANCE = 100;  // further away than this and we stay quiet

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  Serial.begin(9600);
  Serial.println("Parking sensor ready");
}

void loop() {
  int distance = measureDistance();

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  if (distance > 0 && distance <= MAX_DISTANCE) {
    // Map the distance to a beep gap: close means a short gap
    int clamped = constrain(distance, MIN_DISTANCE, MAX_DISTANCE);
    int beepGap = map(clamped, MIN_DISTANCE, MAX_DISTANCE, 60, 900);

    tone(BUZZER_PIN, 2000, 50);
    delay(beepGap);
  } else {
    // Nothing in range, stay silent
    noTone(BUZZER_PIN);
    delay(200);
  }
}

// Returns the distance in whole centimetres
int measureDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH);
  int distance = duration * 0.034 / 2;
  return distance;
}

