/*
  HC-SR04 on an ESP32 with a simple average filter
  Takes several readings and averages them so the value is steadier.
  Note: the HC-SR04 echo pin is 5V, so use a voltage divider on ECHO.
  Board: ESP32 Dev Module
*/

// --- Pin setup ---
const int TRIG_PIN = 5;
const int ECHO_PIN = 18;

// --- Measurement settings ---
const int SAMPLE_COUNT = 5;            // how many readings to average
const unsigned long ECHO_TIMEOUT = 30000;  // give up after 30 ms

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  Serial.begin(115200);
  Serial.println("ESP32 ultrasonic sensor started");
}

void loop() {
  float total = 0;
  int validSamples = 0;

  for (int i = 0; i < SAMPLE_COUNT; i++) {
    float reading = readDistance();

    // A reading of 0 means the echo never came back
    if (reading > 0) {
      total = total + reading;
      validSamples = validSamples + 1;
    }

    delay(50);
  }

  if (validSamples > 0) {
    float average = total / validSamples;
    Serial.print("Average distance: ");
    Serial.print(average, 1);
    Serial.println(" cm");
  } else {
    Serial.println("No object detected");
  }

  delay(500);
}

// One measurement, returns centimetres or 0 when it times out
float readDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, ECHO_TIMEOUT);

  if (duration == 0) {
    return 0;
  }

  return duration * 0.034 / 2;
}

