/*
  Ultrasonic radar
  A servo sweeps the HC-SR04 from 15 to 165 degrees and prints
  the angle and the distance so a PC program can draw a radar screen.
  Board: Arduino Uno
*/

#include <Servo.h>

// --- Pin setup ---
const int TRIG_PIN = 10;
const int ECHO_PIN = 11;
const int SERVO_PIN = 12;

// --- Sweep limits in degrees ---
const int START_ANGLE = 15;
const int END_ANGLE = 165;

Servo radarServo;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  radarServo.attach(SERVO_PIN);
  Serial.begin(9600);
}

void loop() {
  // Sweep from left to right
  for (int angle = START_ANGLE; angle <= END_ANGLE; angle++) {
    radarServo.write(angle);
    delay(30);
    reportReading(angle);
  }

  // And back again
  for (int angle = END_ANGLE; angle >= START_ANGLE; angle--) {
    radarServo.write(angle);
    delay(30);
    reportReading(angle);
  }
}

// Print one angle and distance pair, separated by a comma
void reportReading(int angle) {
  int distance = calculateDistance();

  Serial.print(angle);
  Serial.print(",");
  Serial.print(distance);
  Serial.println(".");
}

int calculateDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH);
  int distance = duration * 0.034 / 2;
  return distance;
}

