/*
  Control an LED by typing commands in the Serial Monitor
  Commands: on, off, blink, status
  Remember to set the line ending to Newline in the Serial Monitor.
  Board: Arduino Uno
*/

// --- Pin setup ---
const int LED_PIN = 13;   // the built in LED

// Holds the text typed by the user
String command = "";

// Remembers whether the LED is currently on
bool ledIsOn = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  Serial.begin(9600);
  Serial.println("Type on, off, blink or status");
}

void loop() {
  if (Serial.available() > 0) {
    // Read everything up to the newline the Serial Monitor sends
    command = Serial.readStringUntil('\n');
    command.trim();   // remove spaces and the carriage return

    if (command == "on") {
      digitalWrite(LED_PIN, HIGH);
      ledIsOn = true;
      Serial.println("LED is now ON");
    } else if (command == "off") {
      digitalWrite(LED_PIN, LOW);
      ledIsOn = false;
      Serial.println("LED is now OFF");
    } else if (command == "blink") {
      Serial.println("Blinking five times");
      blinkLed(5);
    } else if (command == "status") {
      if (ledIsOn) {
        Serial.println("Status: ON");
      } else {
        Serial.println("Status: OFF");
      }
    } else {
      Serial.print("Unknown command: ");
      Serial.println(command);
    }
  }
}

void blinkLed(int times) {
  for (int i = 0; i < times; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(200);
    digitalWrite(LED_PIN, LOW);
    delay(200);
  }

  // Put the LED back the way the user left it
  digitalWrite(LED_PIN, ledIsOn ? HIGH : LOW);
}

