  pinMode(LED_PIN, OUTPUT);
  analogWrite(LED_PIN, 0);

  Serial.begin(9600);
  Serial.println("Enter a brightness value between 0 and 255");
}

void loop() {
  if (Serial.available() > 0) {
    // parseInt reads the digits the user typed and turns them into a number
    int value = Serial.parseInt();

    // Throw away anything left in the buffer, such as the newline
    while (Serial.available() > 0) {
      Serial.read();
    }

    // Keep the value inside the range analogWrite understands
    brightness = constrain(value, 0, 255);
    analogWrite(LED_PIN, brightness);

    Serial.print("Brightness set to ");
    Serial.println(brightness);

    // Show the value as a rough percentage too
    int percent = map(brightness, 0, 255, 0, 100);
    Serial.print("That is about ");
    Serial.print(percent);
    Serial.println(" percent");
  }
}

