/*
  Serial command parser on an ESP32
  Type commands like:
    led,2,1     turn the LED on pin 2 on
    led,2,0     turn it off
    pwm,4,128   set pin 4 to a PWM value
  Board: ESP32 Dev Module
*/

// --- Pin setup ---
const int STATUS_LED = 2;   // the blue LED on most ESP32 boards

String inputLine = "";

void setup() {
  pinMode(STATUS_LED, OUTPUT);

  Serial.begin(115200);
  delay(500);
  Serial.println("Command parser ready. Format: command,pin,value");
}

void loop() {
  if (Serial.available() > 0) {
    inputLine = Serial.readStringUntil('\n');
    inputLine.trim();

    if (inputLine.length() > 0) {
      handleCommand(inputLine);
    }
  }
}

// Split the line on the commas and act on the three parts
void handleCommand(String line) {
  int firstComma = line.indexOf(',');
  int secondComma = line.indexOf(',', firstComma + 1);

  if (firstComma < 0 || secondComma < 0) {
    Serial.println("Bad format, use command,pin,value");
    return;
  }

  String action = line.substring(0, firstComma);
  int pin = line.substring(firstComma + 1, secondComma).toInt();
  int value = line.substring(secondComma + 1).toInt();

  if (action == "led") {
    pinMode(pin, OUTPUT);
    digitalWrite(pin, value > 0 ? HIGH : LOW);
    Serial.print("Pin ");
    Serial.print(pin);
    Serial.println(value > 0 ? " set HIGH" : " set LOW");
  } else if (action == "pwm") {
    pinMode(pin, OUTPUT);
    analogWrite(pin, value);
    Serial.print("PWM on pin ");
    Serial.print(pin);
    Serial.print(" set to ");
    Serial.println(value);
  } else {
    Serial.print("Unknown action: ");
    Serial.println(action);
  }
}

