  Blink without delay
  The LED blinks while the loop stays free to do other work.
  Board: Arduino Uno
*/

// --- Pin setup ---
const int LED_PIN = 13;

// How long the LED stays in each state, in milliseconds
const unsigned long BLINK_INTERVAL = 1000;

// Remembers the last time the LED changed
unsigned long previousMillis = 0;

// Current state of the LED
int ledState = LOW;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Blink without delay demo");
}

void loop() {
  // Read the clock once at the top of the loop
  unsigned long currentMillis = millis();

  // Has enough time passed since the last change?
  if (currentMillis - previousMillis >= BLINK_INTERVAL) {
    previousMillis = currentMillis;

    // Flip the LED to the other state
    if (ledState == LOW) {
      ledState = HIGH;
    } else {
      ledState = LOW;
    }

    digitalWrite(LED_PIN, ledState);
  }

  // Any other code here still runs at full speed
}

