const int LED_SLOW = 9;

// --- Intervals in milliseconds ---
const unsigned long FAST_INTERVAL = 250;
const unsigned long SLOW_INTERVAL = 1200;
const unsigned long PRINT_INTERVAL = 2000;

// Each job needs its own timer variable
unsigned long lastFastToggle = 0;
unsigned long lastSlowToggle = 0;
unsigned long lastPrint = 0;

int fastState = LOW;
int slowState = LOW;
unsigned long secondsRunning = 0;

