  if (now - lastSlowToggle >= SLOW_INTERVAL) {
    lastSlowToggle = now;
    slowState = !slowState;
    digitalWrite(LED_SLOW, slowState);
  }

  // Job 3: heartbeat message
  if (now - lastPrint >= PRINT_INTERVAL) {
    lastPrint = now;
    secondsRunning = now / 1000;
    Serial.print("Uptime: ");
    Serial.print(secondsRunning);
    Serial.println(" seconds");
  }
}

