/*
  Button debounce with millis
  A mechanical button bounces for a few milliseconds when pressed,
  so we ignore any change that happens too soon after the last one.
  Board: Arduino Uno
*/

// --- Pin setup ---
const int BUTTON_PIN = 2;   // button to GND
const int LED_PIN = 13;

// How long the signal must be steady before we believe it
const unsigned long DEBOUNCE_DELAY = 50;

int ledState = LOW;
int buttonState = HIGH;        // the debounced reading
int lastButtonReading = HIGH;  // the previous raw reading

unsigned long lastDebounceTime = 0;
int pressCount = 0;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, ledState);

  Serial.begin(9600);
  Serial.println("Press the button to toggle the LED");
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // The reading changed, so restart the timer
  if (reading != lastButtonReading) {
    lastDebounceTime = millis();
  }

  // The reading has been steady long enough to trust it
  if (millis() - lastDebounceTime > DEBOUNCE_DELAY) {
    if (reading != buttonState) {
      buttonState = reading;

      // Only act on a real press, not on the release
      if (buttonState == LOW) {
        ledState = !ledState;
        digitalWrite(LED_PIN, ledState);

        pressCount = pressCount + 1;
        Serial.print("Press number ");
        Serial.println(pressCount);
      }
    }
  }

  lastButtonReading = reading;
}

