/*
  Non blocking beeper
  The buzzer beeps once a second without ever calling delay,
  so the loop can keep reading the switch at full speed.
  Board: Arduino Uno
*/

// --- Pin setup ---
const int BUZZER_PIN = 8;
const int SWITCH_PIN = 4;   // slide switch to GND, enables the beeping
const int LED_PIN = 13;

// --- Beep timing ---
const unsigned long BEEP_ON_TIME = 100;    // how long each beep lasts
const unsigned long BEEP_OFF_TIME = 900;   // silence between beeps
const int BEEP_FREQ = 1200;

unsigned long lastChange = 0;
bool beeping = false;

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(SWITCH_PIN, INPUT_PULLUP);

  Serial.begin(9600);
  Serial.println("Slide the switch on to start beeping");
}

void loop() {
  unsigned long now = millis();
  bool enabled = (digitalRead(SWITCH_PIN) == LOW);

  if (!enabled) {
    // Switch is off, make sure everything is quiet
    noTone(BUZZER_PIN);
    digitalWrite(LED_PIN, LOW);
    beeping = false;
    lastChange = now;
    return;
  }

  if (beeping) {
    // The beep is running, is it time to stop?
    if (now - lastChange >= BEEP_ON_TIME) {
      noTone(BUZZER_PIN);
      digitalWrite(LED_PIN, LOW);
      beeping = false;
      lastChange = now;
    }
  } else {
    // We are in the silent gap, is it time for the next beep?
    if (now - lastChange >= BEEP_OFF_TIME) {
      tone(BUZZER_PIN, BEEP_FREQ);
      digitalWrite(LED_PIN, HIGH);
      beeping = true;
      lastChange = now;
    }
  }
}

