/*
  Non blocking distance polling
  The ultrasonic sensor is read five times a second using millis,
  while an LED keeps blinking on its own schedule.
  Board: Arduino Uno
*/

// --- Ultrasonic pins ---
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

// --- Indicator pins ---
const int WARN_LED = 7;
const int HEARTBEAT_LED = 13;

// --- Timing in milliseconds ---
const unsigned long MEASURE_INTERVAL = 200;
const unsigned long HEARTBEAT_INTERVAL = 500;

// --- Warning threshold in centimetres ---
const int WARN_DISTANCE = 20;

unsigned long lastMeasure = 0;
unsigned long lastHeartbeat = 0;

int heartbeatState = LOW;
float lastDistance = 0;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(WARN_LED, OUTPUT);
  pinMode(HEARTBEAT_LED, OUTPUT);

  Serial.begin(9600);
  Serial.println("Non blocking distance monitor");
}

void loop() {
  unsigned long now = millis();

  // Task 1: take a distance reading now and then
  if (now - lastMeasure >= MEASURE_INTERVAL) {
    lastMeasure = now;
    lastDistance = readDistanceCm();

    Serial.print("Distance: ");
    Serial.print(lastDistance);
    Serial.println(" cm");

    if (lastDistance > 0 && lastDistance < WARN_DISTANCE) {
      digitalWrite(WARN_LED, HIGH);
    } else {
      digitalWrite(WARN_LED, LOW);
    }
  }

  // Task 2: keep the heartbeat LED blinking
  if (now - lastHeartbeat >= HEARTBEAT_INTERVAL) {
    lastHeartbeat = now;
    heartbeatState = !heartbeatState;
    digitalWrite(HEARTBEAT_LED, heartbeatState);
  }
}

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 25000);
  if (duration == 0) {
    return 0;
  }

  return duration * 0.034 / 2;
}
